#![forbid(unsafe_code)]
//! Bounded, u16-prefixed frames with a deliberately small public API.
//!
//! `Frame` has private representation. A client obtains it through
//! `Frame::try_from_payload`, but cannot construct an unchecked value.
//!
//! ```compile_fail
//! use frame_protocol::Frame;
//!
//! let _ = Frame { payload: Vec::new() };
//! ```
//!
//! `FrameError` is non-exhaustive from its first public release. External
//! clients must retain a wildcard when matching it.
//!
//! ```compile_fail
//! use frame_protocol::FrameError;
//!
//! fn describe(error: FrameError) -> &'static str {
//!     match error {
//!         FrameError::PayloadTooLarge { .. } => "too large",
//!         FrameError::Io { .. } => "io",
//!     }
//! }
//! ```
//!
//! These doctests compile as downstream crates, so they exercise real crate
//! privacy and `#[non_exhaustive]`. Unit tests inside this crate cannot prove
//! either boundary.

use std::error::Error;
use std::fmt;
use std::io::{self, Read, Write};

/// Largest payload representable by the two-byte wire prefix.
pub const MAX_PAYLOAD_BYTES: usize = u16::MAX as usize;

/// An owned payload whose length fits in a u16 wire prefix.
#[derive(Clone, Eq, PartialEq)]
pub struct Frame {
    payload: Vec<u8>,
}

#[cfg(feature = "format")]
impl serde::Serialize for Frame {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        serializer.serialize_bytes(&self.payload)
    }
}

impl Frame {
    /// Validates the payload before it becomes a frame.
    pub fn try_from_payload(payload: Vec<u8>) -> Result<Self, FrameError> {
        validate_payload_len(payload.len(), u16::MAX)?;
        Ok(Self { payload })
    }

    /// Returns the validated payload bytes.
    pub fn payload(&self) -> &[u8] {
        &self.payload
    }

    /// Returns the payload length.
    pub fn len(&self) -> usize {
        self.payload.len()
    }

    /// Reports whether the frame has an empty payload.
    pub fn is_empty(&self) -> bool {
        self.payload.is_empty()
    }

    fn from_validated(payload: Vec<u8>) -> Self {
        Self { payload }
    }
}

impl fmt::Debug for Frame {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("Frame")
            .field("len", &self.payload.len())
            .finish()
    }
}

/// A machine-readable framing failure.
///
/// The enum is non-exhaustive so a future release may add a variant. This is
/// protective only when present in the initial public release: adding the
/// attribute later can break existing exhaustive downstream matches.
#[non_exhaustive]
#[derive(Debug)]
pub enum FrameError {
    /// A payload cannot fit under the requested u16 limit.
    PayloadTooLarge {
        /// The supplied or declared byte count.
        actual: usize,
        /// The configured maximum byte count.
        maximum: u16,
    },
    /// An I/O operation failed. The original error remains available through
    /// `Error::source`.
    Io {
        /// The operation which attempted I/O.
        operation: &'static str,
        /// The unmodified I/O cause.
        source: io::Error,
    },
}

impl FrameError {
    fn io(operation: &'static str, source: io::Error) -> Self {
        Self::Io { operation, source }
    }
}

impl fmt::Display for FrameError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PayloadTooLarge { actual, maximum } => {
                write!(
                    formatter,
                    "frame payload of {actual} bytes exceeds {maximum}"
                )
            }
            Self::Io { operation, .. } => formatter.write_str(operation),
        }
    }
}

impl Error for FrameError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::PayloadTooLarge { .. } => None,
            Self::Io { source, .. } => Some(source),
        }
    }
}

/// Original public callable API: reads one u16 big-endian frame.
///
/// Its exact signature remains part of the public compatibility contract:
/// `fn(&mut dyn Read, u16) -> Result<Frame, FrameError>`. The configured
/// limit is checked after the two-byte prefix and before payload allocation or
/// payload reads.
pub fn read_frame(reader: &mut dyn Read, maximum: u16) -> Result<Frame, FrameError> {
    read_frame_inner(reader, maximum)
}

/// Additive spelling for callers choosing the explicit checked terminology.
///
/// It preserves the original wire format and behavior of `read_frame`.
pub fn read_frame_checked(reader: &mut dyn Read, maximum: u16) -> Result<Frame, FrameError> {
    read_frame(reader, maximum)
}

/// Original public callable API: writes a validated frame.
pub fn write_frame(writer: &mut dyn Write, frame: &Frame) -> Result<(), FrameError> {
    write_frame_inner(writer, frame)
}

/// Writes a frame only when it fits the configured limit.
///
/// The limit is checked before this function writes any prefix or payload
/// bytes. Once I/O starts, a partial writer can still have produced bytes and
/// its original error remains the source.
pub fn write_frame_checked(
    writer: &mut dyn Write,
    frame: &Frame,
    maximum: u16,
) -> Result<(), FrameError> {
    validate_payload_len(frame.len(), maximum)?;
    write_frame(writer, frame)
}

fn read_frame_inner(reader: &mut dyn Read, maximum: u16) -> Result<Frame, FrameError> {
    let mut prefix = [0_u8; 2];
    reader
        .read_exact(&mut prefix)
        .map_err(|source| FrameError::io("read frame length", source))?;
    let declared = usize::from(u16::from_be_bytes(prefix));
    validate_payload_len(declared, maximum)?;

    // The policy check above deliberately comes before this allocation and
    // before any payload read.
    let mut payload = vec![0_u8; declared];
    reader
        .read_exact(&mut payload)
        .map_err(|source| FrameError::io("read frame payload", source))?;
    Ok(Frame::from_validated(payload))
}

fn write_frame_inner(writer: &mut dyn Write, frame: &Frame) -> Result<(), FrameError> {
    let length = u16::try_from(frame.len()).expect("Frame validates its u16 length");
    writer
        .write_all(&length.to_be_bytes())
        .and_then(|()| writer.write_all(frame.payload()))
        .map_err(|source| FrameError::io("write frame", source))
}

fn validate_payload_len(actual: usize, maximum: u16) -> Result<(), FrameError> {
    if actual > usize::from(maximum) {
        return Err(FrameError::PayloadTooLarge { actual, maximum });
    }
    Ok(())
}

/// The original trait implemented by existing frame sources.
///
/// It remains dyn-compatible and has no added required methods.
pub trait FrameReader {
    /// Returns the next frame under the supplied payload limit.
    fn read_frame(&mut self, maximum: u16) -> Result<Frame, FrameError>;
}

/// Additive methods for `FrameReader` implementers and trait objects.
///
/// The blanket implementation has no `Clone`, `Debug`, or `Sized` bound, so an
/// old implementer and `&mut dyn FrameReader` can use this method.
pub trait FrameReaderExt: FrameReader {
    /// Calls the original method through a checked-name compatibility surface.
    fn read_frame_checked(&mut self, maximum: u16) -> Result<Frame, FrameError> {
        self.read_frame(maximum)
    }
}

impl<T: FrameReader + ?Sized> FrameReaderExt for T {}

/// Compatibility import paths for callers using the original functions.
pub mod legacy {
    pub use super::{read_frame, write_frame};
}

/// Formats opt-in diagnostics without changing the default feature surface.
#[cfg(feature = "diagnostics")]
pub fn diagnostic_summary(frame: &Frame) -> String {
    format!("frame payload length: {} bytes", frame.len())
}

/// Returns whether this crate's format feature can consume a validated frame.
#[cfg(feature = "format")]
pub fn format_supports_serialize(frame: &Frame) -> bool {
    fn requires_serialize<T: serde::Serialize>(_: &T) {}

    requires_serialize(frame);
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn opaque_constructor_accepts_empty_and_exact_u16_boundary() {
        assert!(Frame::try_from_payload(Vec::new()).unwrap().is_empty());
        assert_eq!(
            Frame::try_from_payload(vec![7; MAX_PAYLOAD_BYTES])
                .unwrap()
                .len(),
            MAX_PAYLOAD_BYTES
        );
    }

    #[test]
    fn opaque_constructor_rejects_one_byte_past_u16_boundary() {
        let error = Frame::try_from_payload(vec![0; MAX_PAYLOAD_BYTES + 1]).unwrap_err();
        assert!(matches!(
            error,
            FrameError::PayloadTooLarge {
                actual: 65_536,
                maximum: u16::MAX
            }
        ));
    }

    #[test]
    fn empty_payload_is_a_valid_frame() {
        let bytes = [0_u8, 0];
        assert_eq!(read_frame(&mut bytes.as_slice(), 0).unwrap().payload(), []);
    }

    #[test]
    fn maximum_is_checked_before_payload_allocation_or_read() {
        struct PrefixOnly {
            reads: usize,
        }

        impl Read for PrefixOnly {
            fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
                self.reads += 1;
                if self.reads == 1 {
                    buffer[..2].copy_from_slice(&[0, 4]);
                    Ok(2)
                } else {
                    panic!("payload must not be read after an over-limit prefix");
                }
            }
        }

        let mut reader = PrefixOnly { reads: 0 };
        let error = read_frame(&mut reader, 3).unwrap_err();
        assert!(matches!(
            error,
            FrameError::PayloadTooLarge {
                actual: 4,
                maximum: 3
            }
        ));
        assert_eq!(reader.reads, 1);
    }

    #[test]
    fn eof_and_truncation_preserve_an_io_source() {
        for bytes in [Vec::new(), vec![0], vec![0, 2, 9]] {
            let error = read_frame(&mut bytes.as_slice(), 8).unwrap_err();
            let source = error
                .source()
                .and_then(|source| source.downcast_ref::<io::Error>())
                .expect("I/O error must be retained as the source");
            assert_eq!(source.kind(), io::ErrorKind::UnexpectedEof);
        }
    }

    #[test]
    fn source_type_and_kind_survive_a_failing_reader() {
        struct Failing;

        impl Read for Failing {
            fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
                Err(io::Error::new(io::ErrorKind::PermissionDenied, "denied"))
            }
        }

        let error = read_frame(&mut Failing, 8).unwrap_err();
        let source = error
            .source()
            .and_then(|source| source.downcast_ref::<io::Error>())
            .expect("I/O source type is preserved");
        assert_eq!(source.kind(), io::ErrorKind::PermissionDenied);
    }

    #[test]
    fn checked_writer_rejects_before_output() {
        struct NeverWrites(bool);

        impl Write for NeverWrites {
            fn write(&mut self, _: &[u8]) -> io::Result<usize> {
                self.0 = true;
                panic!("over-limit frame must not reach a writer");
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let frame = Frame::try_from_payload(vec![1, 2, 3, 4]).unwrap();
        let mut writer = NeverWrites(false);
        assert!(matches!(
            write_frame_checked(&mut writer, &frame, 3),
            Err(FrameError::PayloadTooLarge {
                actual: 4,
                maximum: 3
            })
        ));
        assert!(!writer.0);
    }

    #[test]
    fn partial_writer_keeps_its_source_and_observable_prefix() {
        struct PartialWriter {
            calls: usize,
            bytes: Vec<u8>,
        }

        impl Write for PartialWriter {
            fn write(&mut self, buffer: &[u8]) -> io::Result<usize> {
                self.calls += 1;
                if self.calls == 1 {
                    self.bytes.push(buffer[0]);
                    Ok(1)
                } else {
                    Err(io::Error::new(io::ErrorKind::BrokenPipe, "closed"))
                }
            }

            fn flush(&mut self) -> io::Result<()> {
                Ok(())
            }
        }

        let frame = Frame::try_from_payload(vec![9, 8]).unwrap();
        let mut writer = PartialWriter {
            calls: 0,
            bytes: Vec::new(),
        };
        let error = write_frame(&mut writer, &frame).unwrap_err();
        assert_eq!(writer.bytes, [0]);
        let source = error
            .source()
            .and_then(|source| source.downcast_ref::<io::Error>())
            .expect("partial-write cause remains available");
        assert_eq!(source.kind(), io::ErrorKind::BrokenPipe);
    }

    #[cfg(feature = "diagnostics")]
    #[test]
    fn diagnostics_are_an_explicit_additive_feature() {
        let frame = Frame::try_from_payload(vec![1, 2]).unwrap();
        assert_eq!(diagnostic_summary(&frame), "frame payload length: 2 bytes");
    }

    #[cfg(feature = "format")]
    #[test]
    fn format_feature_adds_serialize_without_bypassing_validation() {
        fn requires_serialize<T: serde::Serialize>(_: &T) {}

        let frame = Frame::try_from_payload(vec![1, 2]).unwrap();
        requires_serialize(&frame);
        assert_eq!(frame.payload(), [1, 2]);
    }
}

