use std::error::Error as _;
use std::io::{self, Read};

use frame_protocol::{
    Frame, FrameError, FrameReader, FrameReaderExt, read_frame, read_frame_checked, write_frame,
};

struct ExistingReader {
    input: Vec<u8>,
}

impl FrameReader for ExistingReader {
    fn read_frame(&mut self, maximum: u16) -> Result<Frame, FrameError> {
        let mut bytes = self.input.as_slice();
        read_frame(&mut bytes, maximum)
    }
}

#[test]
fn original_function_pointer_signature_and_behavior_remain_callable() {
    let old: fn(&mut dyn Read, u16) -> Result<Frame, FrameError> = read_frame;
    let mut bytes = [0_u8, 2, 10, 11].as_slice();
    let frame = old(&mut bytes, 2).unwrap();
    assert_eq!(frame.payload(), [10, 11]);

    let old_write: fn(&mut dyn io::Write, &Frame) -> Result<(), FrameError> = write_frame;
    let mut encoded = Vec::new();
    old_write(&mut encoded, &frame).unwrap();
    assert_eq!(encoded, [0, 2, 10, 11]);

    let via_module: fn(&mut dyn Read, u16) -> Result<Frame, FrameError> =
        frame_protocol::legacy::read_frame;
    let mut bytes = [0_u8, 1, 23].as_slice();
    let frame = via_module(&mut bytes, 1).unwrap();
    let old_write: fn(&mut dyn io::Write, &Frame) -> Result<(), FrameError> =
        frame_protocol::legacy::write_frame;
    let mut encoded = Vec::new();
    old_write(&mut encoded, &frame).unwrap();
    assert_eq!(encoded, [0, 1, 23]);
}

#[test]
fn old_non_clone_non_debug_implementer_and_dyn_receiver_get_the_extension() {
    let mut old_implementer = ExistingReader {
        input: vec![0, 1, 42],
    };
    let object: &mut dyn FrameReader = &mut old_implementer;
    let frame = object.read_frame_checked(1).unwrap();
    assert_eq!(frame.payload(), [42]);
}

#[test]
fn additive_function_has_the_same_validated_wire_behavior() {
    let mut bytes = [0_u8, 0].as_slice();
    assert!(read_frame_checked(&mut bytes, 0).unwrap().is_empty());
}

#[test]
fn public_error_source_is_typed_instead_of_parsed_from_display() {
    struct Broken;

    impl Read for Broken {
        fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
            Err(io::Error::new(io::ErrorKind::ConnectionReset, "reset"))
        }
    }

    let error = read_frame(&mut Broken, 8).unwrap_err();
    let source = error
        .source()
        .and_then(|source| source.downcast_ref::<io::Error>())
        .expect("source must retain the concrete I/O error");
    assert_eq!(source.kind(), io::ErrorKind::ConnectionReset);
}

#[derive(Debug)]
struct OriginalCause(std::sync::Arc<()>);

impl std::fmt::Display for OriginalCause {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("original transport failure")
    }
}

impl std::error::Error for OriginalCause {}

fn assert_original_cause(error: &FrameError, token: &std::sync::Arc<()>) {
    let source = error.source().unwrap().downcast_ref::<io::Error>().unwrap();
    assert_eq!(source.kind(), io::ErrorKind::ConnectionReset);
    let cause = source
        .get_ref()
        .unwrap()
        .downcast_ref::<OriginalCause>()
        .unwrap();
    assert!(std::sync::Arc::ptr_eq(&cause.0, token));
}

#[test]
fn both_read_stages_preserve_the_original_owned_cause() {
    struct FailingRead {
        prefix: io::Cursor<Vec<u8>>,
        failure: Option<io::Error>,
    }
    impl Read for FailingRead {
        fn read(&mut self, bytes: &mut [u8]) -> io::Result<usize> {
            let count = self.prefix.read(bytes)?;
            if count > 0 || bytes.is_empty() {
                Ok(count)
            } else {
                match self.failure.take() {
                    Some(error) => Err(error),
                    None => Ok(0),
                }
            }
        }
    }
    for (prefix, expected_operation) in [
        (None, "read frame length"),
        (Some([0, 1]), "read frame payload"),
    ] {
        let token = std::sync::Arc::new(());
        let mut reader = FailingRead {
            prefix: io::Cursor::new(prefix.map_or_else(Vec::new, Vec::from)),
            failure: Some(io::Error::new(
                io::ErrorKind::ConnectionReset,
                OriginalCause(std::sync::Arc::clone(&token)),
            )),
        };
        let error = read_frame(&mut reader, 1).unwrap_err();
        assert!(
            matches!(&error, FrameError::Io { operation, .. } if *operation == expected_operation)
        );
        assert_original_cause(&error, &token);
        assert_eq!(error.to_string(), expected_operation);
        assert_eq!(
            error.source().unwrap().to_string(),
            "original transport failure"
        );
    }
}

#[test]
fn write_failure_preserves_the_original_owned_cause() {
    struct FailingWrite(Option<io::Error>);
    impl io::Write for FailingWrite {
        fn write(&mut self, _: &[u8]) -> io::Result<usize> {
            Err(self.0.take().unwrap())
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }
    let token = std::sync::Arc::new(());
    let mut writer = FailingWrite(Some(io::Error::new(
        io::ErrorKind::ConnectionReset,
        OriginalCause(std::sync::Arc::clone(&token)),
    )));
    let frame = Frame::try_from_payload(vec![1]).unwrap();
    let error = write_frame(&mut writer, &frame).unwrap_err();
    assert!(matches!(&error, FrameError::Io { operation, .. } if *operation == "write frame"));
    assert_original_cause(&error, &token);
}

use std::error::Error;
use std::io::Cursor;

use frame_protocol::{read_frame, write_frame_checked};

fn main() -> Result<(), Box<dyn Error>> {
    let wire = vec![0, 4, b'r', b'u', b's', b't'];
    let mut input = Cursor::new(wire.clone());
    let frame = read_frame(&mut input, 64)?;

    let mut output = Vec::new();
    write_frame_checked(&mut output, &frame, 64)?;
    assert_eq!(output, wire);
    println!("frame-probe: payload={} bytes", frame.len());

    #[cfg(feature = "diagnostics")]
    println!(
        "diagnostics: {}",
        frame_protocol::diagnostic_summary(&frame)
    );

    Ok(())
}

use std::process::Command;

#[cfg(not(feature = "diagnostics"))]
#[test]
fn process_completes_with_a_finite_default_demo() {
    let output = Command::new(env!("CARGO_BIN_EXE_frame-probe"))
        .output()
        .expect("launch frame-probe");
    assert!(
        output.status.success(),
        "frame-probe failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        String::from_utf8(output.stdout).unwrap(),
        "frame-probe: payload=4 bytes\n"
    );
    assert!(String::from_utf8(output.stderr).unwrap().is_empty());
}

#[cfg(feature = "diagnostics")]
#[test]
fn diagnostics_feature_changes_only_the_opt_in_process_output() {
    let output = Command::new(env!("CARGO_BIN_EXE_frame-probe"))
        .output()
        .expect("launch frame-probe");
    assert!(
        output.status.success(),
        "frame-probe failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        String::from_utf8(output.stdout).unwrap(),
        "frame-probe: payload=4 bytes\ndiagnostics: frame payload length: 4 bytes\n"
    );
}

#[cfg(feature = "format")]
#[test]
fn format_feature_activates_library_serialize_consumer() {
    let frame = frame_protocol::Frame::try_from_payload(vec![1, 2]).unwrap();
    assert!(frame_protocol::format_supports_serialize(&frame));
}
